const frame = context.panel.data.series?.[0];
if (!frame) { context.grafana.notifyError(['SharePoint Access','Site registry unavailable']); return; }
const values = name => { const f=frame.fields.find(x=>x.name===name);return f ? Array.from(f.values):[]; };
const ids=values('Site ID'), names=values('Site'), states=values('Enabled'), revisions=values('Revision');
const options=ids.map((id,i)=>({id:String(id),label:String(names[i])+' ['+(states[i]?'Enabled':'Disabled')+']',value:String(id)}));
const selected=options[0]?.value||'';
const h=(opts=[])=>({showIf:()=>true,disableIf:()=>false,getOptions:()=>opts});
context.panel.onChangeElements([
 {uid:'site',id:'site',title:'SharePoint site',type:'select',optionsSource:'Custom',options,allowCustomValue:false,value:selected,labelWidth:20,section:'Site access',tooltip:'Discovered sites only',helpers:h(options)},
 {uid:'enable',id:'enable',title:'Enable Jason access',type:'checkbox',value:false,labelWidth:20,section:'Site access',tooltip:'Site gate only; does not grant provider writes or document disclosure',helpers:h()},
 {uid:'apply',id:'apply',title:'Apply',type:'button',buttonLabel:'Apply Site Access',show:'form',size:'md',variant:'primary',labelWidth:20,section:'Site access',helpers:h(),customCode:`const get=id=>context.panel.elements.find(e=>e.id===id)?.value;
const site_id=String(get('site')||''), enabled=get('enable')===true;
const url='/api/datasources/proxy/uid/jason-sharepoint-control/sharepoint-control/sites';
fetch(url,{credentials:'same-origin'}).then(async r=>{if(!r.ok)throw Error('Cannot read live site policy');return r.json()})
.then(data=>{const row=(data.sites||[]).find(s=>s.site_id===site_id);if(!row)throw Error('Site not found');
if(!window.confirm((enabled?'Enable':'Disable')+' Jason access to '+row.name+'?'))return null;
return fetch('/api/datasources/proxy/uid/jason-sharepoint-control/sharepoint-control/site-access',{
method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},
body:JSON.stringify({site_id,enabled,expected_revision:row.revision,reason:'Grafana SharePoint Site Access'})})})
.then(async r=>{if(!r)return;const b=await r.json();if(!r.ok)throw Error(b.error||'Change denied');context.grafana.notifySuccess(['SharePoint Access','Setting verified; refresh dashboard']);context.grafana.locationService.reload();})
.catch(e=>context.grafana.notifyError(['SharePoint Access',String(e.message||e)]));`},
 {uid:'refresh',id:'refresh',title:'Refresh',type:'button',buttonLabel:'Refresh site list',show:'form',size:'md',variant:'secondary',labelWidth:20,section:'Site access',helpers:h(),customCode:'context.grafana.locationService.reload();'}
]);
